using V=arkjson::Value;using namespace ark;
static int checks=0;
static void check(bool ok,const std::string& why){++checks;if(!ok)throw std::runtime_error(why);}
static V json(const char* text){V out;check(arkjson::parse(text,out),"Fixture parses");return out;}
static const V& field(const V& value,const char* key){const auto* found=value.find(key);if(!found)throw std::runtime_error(std::string("Missing ")+key);return *found;}
static V data(const V& response){check(!field(response,"isError").b,response.dump());return field(response,"structuredContent");}
static std::string canonicalValue(const V& value){std::string bytes,error;check(encodeDocumentValue(value,bytes,&error),error);return bytes;}
static V prepare(AgentSession& s,V edit){V args=V::makeObj();args.set("action",V::makeStr("prepare"));args.set("expected_revision",V::makeNum((double)s.revision));args.set("edit",std::move(edit));return s.call("geometry_graph",args);}
static void commit(AgentSession& s,V edit){const auto before=documentToJson(s.document);const auto revision=s.revision;const auto prepared=data(prepare(s,std::move(edit)));check(s.revision==revision&&documentToJson(s.document)==before,"Preparation must not publish a graph edit");V args=V::makeObj();args.set("candidate_id",field(prepared,"candidate_id"));args.set("expected_revision",V::makeNum((double)revision));const auto applied=data(s.call("doc_apply",args));check(field(applied,"applied_prepared").b&&field(applied,"features_evaluated").num==0,"Graph Apply must publish the reviewed result without a second geometry pass");check(s.revision==revision+1,"Graph edit did not advance the normal document revision");}
static void reject(AgentSession& s,V edit){const auto before=documentToJson(s.document);const auto revision=s.revision;const auto recipe=edit.dump();const auto response=prepare(s,std::move(edit));check(field(response,"isError").b,"Invalid graph edit was accepted: "+recipe+" / response: "+response.dump());check(s.revision==revision&&documentToJson(s.document)==before,"Rejected graph edit changed authoring or revision");}
