 AgentSession s;s.suppressFailureCapture();const auto meshCommands=geometryNodeCommands078B(s.document,json(R"({"op":"add","recipe":"mesh_net"})"));check(!meshCommands.arr.front().find("native"),"Mesh source must use its existing parameter contract, not native:{}");commit(s,json(R"({"op":"add","recipe":"mesh_net","parameters":{"width":25,"depth":20,"rows":3,"columns":3}})"));commit(s,json(R"({"op":"add","recipe":"mesh_net","parameters":{"width":35,"depth":20,"rows":3,"columns":3}})"));commit(s,json(R"({"op":"add","recipe":"mesh_offset","inputs":[1]})"));
 check(s.document.features.size()==3&&s.document.find(3)->inputs==std::vector<u64>{1},"Mesh operation did not retain its authored link");commit(s,json(R"({"op":"link","source":2,"target":3,"input":0})"));check(s.document.find(3)->inputs==std::vector<u64>{2},"Port reconnection did not retarget the actual feature");
 const auto graph=data(s.call("geometry_graph",json(R"({"action":"inspect"})")));check(field(graph,"nodes").arr.size()==3&&field(graph,"links").arr.size()==1,"Graph snapshot lost nodes or links");check(field(field(graph,"nodes").arr.back(),"domain").str=="mesh","Mesh output domain wrong");
 const auto before=s.revision;V stale=json(R"({"action":"prepare","expected_revision":0,"edit":{"op":"link","source":1,"target":3,"input":0}})");check(field(s.call("geometry_graph",stale),"isError").b&&s.revision==before,"Stale geometry graph request was accepted");
 reject(s,json(R"({"op":"link","source":999999,"target":3,"input":0})"));reject(s,json(R"({"op":"link","source":3,"target":3,"input":0})"));reject(s,json(R"({"op":"disconnect","target":3,"input":0})"));reject(s,json(R"({"op":"link","source":1,"target":3,"input":5})"));
 commit(s,json(R"({"op":"edit","node":1,"parameters":{"width":45}})"));check(s.document.find(1)->p.at("width")=="45","Dimension edit did not persist on the actual mesh source");
