static void sourceOwnership(){
 AgentSession s;s.suppressFailureCapture();V request=json(R"({"action":"prepare","mode":"install","namespace":"gn","program":{"format":"ark.parametric-program.v1","name":"Synthetic graph ownership","parameters":{"w":{"default":12,"min":1}},"functions":{},"body":[{"emit":{"op":"feature.add","type":"box","name":"Body","p":{"dx":"{w}","dy":4,"dz":4}}}]}})");request.set("expected_revision",V::makeNum((double)s.revision));const auto checked=data(s.call("parametric_program",request));V publish=V::makeObj();publish.set("candidate_id",field(checked,"candidate_id"));publish.set("expected_revision",V::makeNum((double)s.revision));data(s.call("doc_apply",publish));check(s.document.features.size()==1,"Program ownership fixture missing output");
 const auto id=s.document.features.front().id;const auto parameters=s.document.features.front().p;const auto binding=canonicalValue(s.document.parametricPrograms);
 auto inspect=[&](){return data(s.call("parametric_program",json(R"({"action":"inspect","namespace":"gn"})")));};
 auto divergenceBlocksRerun=[&](){const auto inspected=inspect();check(field(inspected,"programs").arr.size()==1&&field(field(inspected,"programs").arr.front(),"local_edits").b,"Local node change did not remain an explicitly diverged program output");check(canonicalValue(s.document.parametricPrograms)==binding,"Node edit silently detached or resealed its program ownership");V configure=json(R"({"action":"prepare","mode":"configure","namespace":"gn","values":{"w":14}})");configure.set("expected_revision",V::makeNum((double)s.revision));const auto before=documentToJson(s.document);const auto revision=s.revision;const auto response=s.call("parametric_program",configure);check(field(response,"isError").b&&response.dump().find("PROGRAM_LOCAL_EDITS")!=std::string::npos,"A program rerun overwrote locally changed node output");check(s.revision==revision&&documentToJson(s.document)==before,"Rejected program rerun changed local source");};
 auto undo=[&](){V args=V::makeObj();args.set("expected_revision",V::makeNum((double)s.revision));data(s.call("doc_undo",args));const auto inspected=inspect();check(!field(field(inspected,"programs").arr.front(),"local_edits").b&&canonicalValue(s.document.parametricPrograms)==binding&&s.document.find(id)&&s.document.find(id)->p==parameters,"Undo did not recover the clean program-owned source and binding");};
 V edit=json(R"({"op":"edit","node":1,"parameters":{"dx":13}})");edit.set("node",V::makeNum((double)id));commit(s,edit);divergenceBlocksRerun();undo();
 edit=V::makeObj();edit.set("op",V::makeStr("remove"));edit.set("node",V::makeNum((double)id));commit(s,edit);check(!s.document.find(id),"Node removal did not remove its selected output");divergenceBlocksRerun();undo();
}
static void candidateCleanup(){
 AgentSession s;s.suppressFailureCapture();commit(s,json(R"({"op":"add","recipe":"mesh_net","parameters":{"rows":3,"columns":3}})"));
 auto candidate=[&](double width){V edit=json(R"({"op":"edit","node":1,"parameters":{}})");V parameters=V::makeObj();parameters.set("width",V::makeNum(width));edit.set("parameters",parameters);return data(prepare(s,edit));};
 const auto source=documentToJson(s.document);const auto revision=s.revision;const auto cancelled=candidate(55);const auto id=field(cancelled,"candidate_id").str;check(!s.preparedRecipe(id).isNull(),"Checked preview was not retained");check(s.discardPreparedCandidate(id)&&!s.discardPreparedCandidate(id),"Cancel did not release exactly its candidate / repeated release was not harmless");check(documentToJson(s.document)==source&&s.revision==revision,"Candidate cleanup changed source/revision");
 V publish=V::makeObj();publish.set("candidate_id",V::makeStr(id));publish.set("expected_revision",V::makeNum((double)s.revision));check(field(s.call("doc_apply",publish),"isError").b,"Cancelled candidate could still publish");check(documentToJson(s.document)==source&&s.revision==revision,"Rejected cancelled publication changed source");
 const auto stale=candidate(60);const auto staleId=field(stale,"candidate_id").str;commit(s,json(R"({"op":"edit","node":1,"parameters":{"width":45}})"));const auto changed=documentToJson(s.document);const auto changedRevision=s.revision;publish.set("candidate_id",V::makeStr(staleId));publish.set("expected_revision",V::makeNum((double)changedRevision));check(field(s.call("doc_apply",publish),"isError").b,"Stale checked preview silently rebased");check(s.discardPreparedCandidate(staleId)&&changed==documentToJson(s.document)&&s.revision==changedRevision,"Stale cleanup lost the current edit or retained obsolete geometry");
 const auto applied=candidate(50);publish.set("candidate_id",field(applied,"candidate_id"));publish.set("expected_revision",V::makeNum((double)s.revision));const auto receipt=data(s.call("doc_apply",publish));check(field(receipt,"applied_prepared").b&&field(receipt,"features_evaluated").num==0,"Apply recomputed instead of publishing the reviewed result");check(!s.discardPreparedCandidate(field(applied,"candidate_id").str)&&!s.discardPreparedCandidate("unknown-candidate"),"Consumed/unknown candidate release was not harmless");
}
static void compactPreparation(){
 AgentSession s;s.suppressFailureCapture();commit(s,json(R"({"op":"add","recipe":"mesh_net","name":"Edited node","parameters":{"width":25,"rows":3,"columns":3}})"));commit(s,json(R"({"op":"add","recipe":"mesh_net","name":"Unrelated node","parameters":{"width":35,"rows":3,"columns":3}})"));const auto source=documentToJson(s.document);const auto revision=s.revision;
 const V edit=json(R"({"op":"edit","node":1,"parameters":{"width":40}})");const auto preview=data(prepare(s,edit));check(field(preview,"detail").str=="changes"&&preview.find("summary_scope"),"Node preparation did not declare its changed-row scope");
 for(const char* phase:{"before","after"}){const auto& rows=field(preview,phase);check(field(rows,"partial").b&&field(rows,"features").arr.size()==1&&field(field(rows,"features").arr.front(),"id").num==1,"Unrelated node leaked into compact before/after rows");}
 const auto& result=field(preview,"candidate_result");check(field(result,"response_scope").str=="candidate_status"&&field(result,"feature_count").num==2&&!result.find("features")&&field(result,"features_evaluated").num==1&&field(result,"features_reused").num==1,"Compact preparation lost measured counts or returned the whole design");
 const auto path=std::filesystem::temp_directory_path()/("ark-node-compact-preview-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".png");struct RemoveImage {std::filesystem::path path;~RemoveImage(){std::error_code ignored;std::filesystem::remove(path,ignored);}} cleanup{path};const auto encoded=path.u8string();V capture=V::makeObj();capture.set("candidate_id",field(preview,"candidate_id"));capture.set("expected_revision",V::makeNum((double)revision));capture.set("id",V::makeNum(2));capture.set("view",V::makeStr("iso"));capture.set("inline_image",V::makeBool(false));capture.set("path",V::makeStr(std::string(reinterpret_cast<const char*>(encoded.data()),encoded.size())));const auto snapshot=data(s.call("snapshot",capture));check(field(field(snapshot,"visual_evidence"),"stage").str=="preview"&&std::filesystem::is_regular_file(path),"Compact response discarded unrelated geometry from the retained candidate");
 check(s.discardPreparedCandidate(field(preview,"candidate_id").str)&&s.revision==revision&&documentToJson(s.document)==source,"Cancelling compact preview changed current source");commit(s,edit);check(s.document.find(1)->p.at("width")=="40"&&s.document.find(2)->p.at("width")=="35","Compact prepared publication lost edited or unrelated source");
}
static void boundedInspection(){
 AgentSession s;s.suppressFailureCapture();for(int i=0;i<40;++i){Feature f;f.type=FeatureType::NativeSolid;f.name="Bounded node "+std::to_string(i);f.nativeSpec=json(R"({"op":"box"})");if(!i)f.nativeSpec.set("large_imported_descriptor",V::makeStr(std::string(600000,'q')));if(i)f.inputs={1};s.document.addFeature(f);}
 const auto before=documentToJson(s.document);size_t evaluations=0;auto observer=setEvaluationObserver([&](u64,const std::string&,size_t,size_t,bool,bool){++evaluations;});const auto first=data(s.call("geometry_graph",json(R"({"action":"inspect","limit":7})")));check(field(first,"nodes").arr.size()==7&&field(field(first,"page"),"selected_nodes").num==40&&!field(first,"next_call").isNull(),"Bounded geometry discovery lost its page census");check(first.dump().size()<18000&&first.dump().find("large_imported_descriptor")==std::string::npos,"Large native source leaked into node overview");
 {const auto oldUsage=s.document.usage;const auto oldActivity=s.document.agentActivity;UsageReceipt usage;usage.id="geometry-page-bookkeeping";usage.source="offline-test";usage.provenance="synthetic";usage.missingResponses=1;std::string error;check(addUsageReceipt(s.document,usage,&error)==UsageRecordResult::Added,error);data(s.call("doc_info",json(R"({"detail":"revision","actor":{"kind":"agent","id":"page-reader"}})")));const auto continued=data(s.call("geometry_graph",field(first,"next_call")));check(field(continued,"source_sha256").str==field(first,"source_sha256").str,"Usage/activity-only bookkeeping invalidated a geometry continuation");s.document.usage=oldUsage;s.document.agentActivity=oldActivity;}
 std::set<u64> seen;auto page=first;for(;;){for(const auto& n:field(page,"nodes").arr)check(seen.insert((u64)field(n,"id").num).second,"Geometry continuation repeated a node");if(field(page,"next_call").isNull())break;page=data(s.call("geometry_graph",field(page,"next_call")));}check(seen.size()==40,"Geometry continuation omitted nodes");
 const auto focused=data(s.call("geometry_graph",json(R"({"action":"inspect","ids":[2],"limit":1})")));check(field(focused,"nodes").arr.size()==1&&field(focused,"links").arr.size()==1&&field(focused,"boundary_ids").arr[0].num==1&&!field(focused,"context_call").isNull(),"Focused node inspection hid its outside source link");
 auto next=field(first,"next_call");next.set("limit",V::makeNum(8));check(field(s.call("geometry_graph",next),"isError").b,"Changed geometry page selection accepted a cursor");s.document.features[0].p["width"]="50";check(field(s.call("geometry_graph",field(first,"next_call")),"isError").b,"In-place source edit accepted an old geometry cursor");s.document.features[0].p.erase("width");
 check(field(s.call("geometry_graph",json(R"({"action":"inspect","ids":[999]})")),"isError").b,"Missing selected node accepted");check(field(s.call("geometry_graph",json(R"({"action":"inspect","limit":65})")),"isError").b,"Unbounded geometry page accepted");setEvaluationObserver(observer);check(!evaluations&&before==documentToJson(s.document),"Geometry inspection evaluated or mutated source");
}
